using Beep.OilandGas.Models.Data.ProductionAccounting;
using TheTechIdea.Data.OilGas;
namespace Beep.OilandGas.Web.Services;
public sealed partial class AccountingServiceClient
{
    private const string PaymentRoute="api/accounting/traditional/company-receivables";
    private static void PaymentIdentity(string id){if(!Guid.TryParseExact(id,"N",out var value) || value==Guid.Empty || value.ToString("N")!=id)throw new ArgumentException("The original native payment/receivable UUID is required.");}
    public async Task<CompanySalesPaymentSource> GetCompanySalesPaymentSourceAsync(string receivable,string book,string currency){PaymentIdentity(receivable);var snapshot=_apiClient.CompanySnapshot;if(snapshot.Selection is null)throw new InvalidOperationException("Select the original company/account.");var source=await _apiClient.GetAsync<CompanySalesPaymentSource>(PaymentRoute+"/payment-source/"+Uri.EscapeDataString(receivable)+"?book="+Uri.EscapeDataString(book)+"&currency="+Uri.EscapeDataString(currency)) ??throw new InvalidOperationException("The original native payment source is unavailable.");if(snapshot!=_apiClient.CompanySnapshot)throw new InvalidOperationException("The company/account changed during payment review.");source.Require(snapshot.Selection.Scope,snapshot.Selection.UserId,receivable,book,currency);return CompanyInventorySourceReview.Copy(source);}
    public async Task<AR_PAYMENT> PrepareCompanySalesPaymentAsync(CompanySalesPaymentCommand command){command=CompanyInventorySourceReview.Copy(command);command.Require();var snapshot=_apiClient.CompanySnapshot;var source=command.Source.Ledger;if(snapshot.Selection is null || source.Company!=snapshot.Selection.Scope || source.ActorUserId!=snapshot.Selection.UserId)throw new InvalidOperationException("Return to the original payment company/account.");var row=await _apiClient.PostAsync<CompanySalesPaymentCommand,AR_PAYMENT>(PaymentRoute+"/payment-drafts",command) ??throw new InvalidOperationException("The original payment proposal is unconfirmed.");if(snapshot!=_apiClient.CompanySnapshot || System.Text.Json.JsonSerializer.Serialize(CompanySalesPaymentProof.Require(row).Command)!=System.Text.Json.JsonSerializer.Serialize(command))throw new InvalidOperationException("The exact original native payment outcome/context changed.");return CompanyInventorySourceReview.Copy(row);}
    public async Task<AR_PAYMENT?> GetCompanySalesPaymentDraftAsync(string id){PaymentIdentity(id);var snapshot=_apiClient.CompanySnapshot;if(snapshot.Selection is null)throw new InvalidOperationException("Select the original payment producer company/account.");var row=await _apiClient.GetAsync<AR_PAYMENT>(PaymentRoute+"/payment-recovery/"+Uri.EscapeDataString(id));if(snapshot!=_apiClient.CompanySnapshot)throw new InvalidOperationException("The company/account changed during payment recovery.");if(row is null)return null;var command=CompanySalesPaymentProof.Require(row).Command;if(command.Id!=id || command.Source.Ledger.Company!=snapshot.Selection.Scope || command.Source.Ledger.ActorUserId!=snapshot.Selection.UserId)throw new InvalidOperationException("Another producer/company owns this private payment request.");return CompanyInventorySourceReview.Copy(row);}
}
